arguments.command:
cd /workspace && cat >> /workspace/dev/perf2.py << 'PYEOF'

if which=='big': go(perf.rich_case(q=2,B=2,R=2,cmax=512), 'all-512-exported')
if which=='big2': go(perf.rich_case(q=8,B=8,R=8,cmax=512,J=512,S=64), '512x64')
PYEOF
python3 - << 'EOF'
p=open('/workspace/dev/perf2.py').read()
p=p.replace("elif which=='groups':", """elif which=='big': go(perf.rich_case(q=2,B=2,R=2,cmax=512), 'all-512-exported')
elif which=='big2': go(perf.rich_case(q=8,B=8,R=8,cmax=512,J=512,S=64), '512x64')
elif which=='full': go(perf.rich_case(q=512,B=512,R=4,cmax=512), 'all-at-once')
elif which=='groups':""")
p=p.replace("elif which=='full': go(perf.rich_case(q=512,B=512,R=0,I=512,J=512,S=256), 'all-at-once')\n","")
open('/workspace/dev/perf2.py','w').write(p)
EOF
for t in big big2 full; do LD_LIBRARY_PATH=/workspace/native timeout 900 python3 /workspace/dev/perf2.py $t; done
